  function renderCollection(){const ids=E.names.map((_,i)=>i).filter(i=>filter<0||E.element(i)===filter),pages=Math.ceil(ids.length/12);collectionPage=E.clamp(collectionPage,0,pages-1);$('element-filters').innerHTML=['All dragons',...E.elements].map((x,i)=>'<button data-filter="'+(i-1)+'" class="chip '+(filter===i-1?'active':'')+'">'+x+'</button>').join('');$('element-filters').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=+b.dataset.filter;collectionPage=0;renderCollection();});$('dragons').innerHTML=ids.slice(collectionPage*12,collectionPage*12+12).map(id=>'<button class="dragon-card '+(id===profile.selected?'selected':'')+'" data-select="'+id+'" style="--dragon:'+color(id)+'"><span class="eyebrow">'+E.elements[E.element(id)]+' · '+['HATCHLING','RARE','LEGENDARY'][E.rarity(id)]+'</span>'+miniPortrait(id)+'<h3>'+title(E.names[id])+'</h3><small>'+E.roars[E.element(id)]+' Roar</small><b>'+(owns(id)?id===profile.selected?'SELECTED':'CHOOSE DRAGON':id===144?'FREE ALL 144 + DEFEAT THE LORD':(profile.wins[id]||0)+' / '+required(id)+' VICTORIES')+'</b></button>').join('');$('collection-page').textContent=(collectionPage+1)+' / '+pages;$('collection-prev').onclick=()=>{collectionPage--;renderCollection();};$('collection-next').onclick=()=>{collectionPage++;renderCollection();};$('dragons').querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{const id=+b.dataset.select;if(!owns(id))return toast('Defeat this dragon '+required(id)+' times, or find it in the daily shop. Two-player mode uses only dragons in your own collection.');profile.selected=id;render();});drawPortraits();}
